 {GraphicsTablePropertiesEditor dock(table);dock.resize(550,900);dock.show();app.processEvents();check(dock.findChild<QWidget*>("tableQuick20"),"Selection properties embeds real quick panel");dock.grab().save(out+"/Selection_properties_2.0.png");}
